\encoding UTF8
\copy (SELECT json_build_object('id', q.id, 'subject', q.subject_area, 'exam', q.exam_type, 'q', q.question_text, 'a', q.option_a, 'b', q.option_b, 'c', q.option_c, 'd', q.option_d, 'e', q.option_e, 'key', q.correct_answer, 'status', q.quality_review_status, 'tier', q.pipeline_metadata::jsonb->>'match_tier') FROM question_bank q WHERE q.is_active AND q.subject_area IN ('TARIH','EDEBIYAT','BIYOLOJI','COGRAFYA','GENEL','SOSYAL','FEN') AND q.quality_review_status IN ('unverified','pending','auto_judged_high') AND q.id NOT IN (SELECT id FROM v_safe_for_beta) AND q.correct_answer IN ('A','B','C','D','E') AND q.option_a IS NOT NULL AND q.option_b IS NOT NULL AND q.option_c IS NOT NULL AND q.option_d IS NOT NULL AND q.option_e IS NOT NULL AND q.word_count >= 5 AND (length(q.question_text)-length(replace(q.question_text,'$','')))%2 = 0 AND NOT (q.question_text ~* '^yukar(ı|ıdaki)' AND (q.pipeline_metadata::jsonb->'ai_extras'->>'has_diagram')::boolean IS NOT TRUE) AND NOT (q.question_text ~* '^bu (parça|şekil|tablo|grafik|diyalog)' AND (q.pipeline_metadata::jsonb->'ai_extras'->>'has_diagram')::boolean IS NOT TRUE) ORDER BY md5(q.id) LIMIT 300) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_faz_d/master.csv' CSV
